  const name = BOSS_PATTERNS[outcome.wave]?.name || '보스';
  if(outcome.total===4)return 'W'+outcome.wave+' '+name+' · 처치 '+outcome.kills+'/4 · 돌파 '+outcome.escapes+'/4'+(outcome.kills?' · 증강 1회':outcome.escapes===4?' · 증강 없음':'');
